function readTime(value: unknown): number {
    if (typeof value === 'number') return value;
    if (typeof value !== 'string' || value.trim() === '') return NaN;
    return /^-?\d+(\.\d+)?$/.test(value.trim()) ? +value : parseTimeValue(value.trim());
